import { channelRoutePath, targetLabel } from "../channels/github/forward.js";
import { CliError, errorCodeForStatus } from "./cli/errors.js";
import { describeError, unknownErrorCode } from "./describe-error.js";
import { CLI_COMMAND_NAME as CLI } from "./distribution.js";
import { isRecord } from "./is-record.js";
import { mergeRequestHeaders } from "./request-headers.js";
import { selectTeamsChannelProfiles, TEAMS_CHANNEL_KIND, teamsTarget, } from "./teams-channel-profile.js";
import { ensureDevTunnel, openDevTunnel, } from "./teams-devtunnel.js";
import { startTeamsPathProxy } from "./teams-tunnel-proxy.js";
import { openTunnelProcess } from "./tunnel-process.js";
const DEFAULT_HOST = "127.0.0.1";
const DEFAULT_PORT = 3000;
export function teamsChannelTargets(agents) {
    return agents.flatMap(({ slug, info }) => info.channels
        .filter((channel) => channel.kind === TEAMS_CHANNEL_KIND)
        .map((channel) => teamsTarget({ slug, channelId: channel.id, routes: channel.routes })));
}
export function teamsMessagingEndpoint(baseUrl, target) {
    return `${baseUrl.replace(/\/+$/, "")}${channelRoutePath(target)}`;
}
const QUICK_TUNNEL_URL = /https:\/\/[a-z0-9-]+\.trycloudflare\.com(?![a-z0-9.-])/gi;
/** cloudflared also logs `https://api.trycloudflare.com` when the tunnel request fails. */
export function parseQuickTunnelUrl(line) {
    for (const match of line.matchAll(QUICK_TUNNEL_URL)) {
        const url = new URL(match[0]);
        if (url.hostname !== "api.trycloudflare.com") {
            return url.origin;
        }
    }
    return undefined;
}
export const CLOUDFLARED_INSTALL_URL = "https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/downloads/";
const CLOUDFLARED_INSTALL_HINT = `Install cloudflared from ${CLOUDFLARED_INSTALL_URL}`;
export async function openQuickTunnel(input) {
    return openTunnelProcess({
        command: "cloudflared",
        args: ["tunnel", "--no-autoupdate", "--url", input.localUrl],
        signal: input.signal,
        spawnImpl: input.spawnImpl,
        timeoutMs: input.timeoutMs,
        parseUrl: parseQuickTunnelUrl,
        program: "cloudflared",
        installHint: CLOUDFLARED_INSTALL_HINT,
    });
}
function whenAborted(signal) {
    return new Promise((resolveAbort) => {
        if (signal.aborted) {
            resolveAbort();
            return;
        }
        signal.addEventListener("abort", () => resolveAbort(), { once: true });
    });
}
const TUNNEL_TEXT = {
    cloudflared: {
        opening: (localUrl) => `Opening a cloudflared quick tunnel to ${localUrl}, where the agent must be serving.\n`,
        label: "cloudflared",
        urlNote: () => "The URL changes each time the tunnel starts.",
        apply: (count) => count === 1
            ? "Set it on the Azure Bot: Configuration, Messaging endpoint, Apply."
            : "Set each on its agent's Azure Bot: Configuration, Messaging endpoint, Apply.",
    },
    devtunnel: {
        opening: (localUrl) => `Opening a dev tunnel to ${localUrl}, where the agent must be serving.\n`,
        label: "devtunnel",
        urlNote: (tunnelId) => `The URL stays the same while dev tunnel ${tunnelId} exists. Microsoft deletes a dev tunnel after 30 days without use, and the next start creates it again under the same id.`,
        apply: (count) => count === 1
            ? "Set it on the Azure Bot once: Configuration, Messaging endpoint, Apply."
            : "Set each on its agent's Azure Bot once: Configuration, Messaging endpoint, Apply.",
        idleWarning: "--tunnel devtunnel had no effect because no agent has a Teams channel.",
    },
};
function formatTunnelReady(input) {
    const endpoints = input.targets.map((target) => ({
        label: targetLabel(target),
        endpoint: teamsMessagingEndpoint(input.publicUrl, target),
    }));
    if (input.json) {
        const payload = { endpoints, localUrl: input.localUrl, tunnel: input.text.label };
        if (input.tunnelId !== undefined) {
            payload.tunnelId = input.tunnelId;
        }
        return `${JSON.stringify(payload)}\n`;
    }
    const width = Math.max(...endpoints.map(({ label }) => label.length));
    const lines = endpoints.length === 1
        ? [
            "Teams messaging endpoint:",
            ...endpoints.map(({ endpoint }) => `  ${endpoint}`),
            input.text.apply(1),
        ]
        : [
            "Teams messaging endpoints:",
            ...endpoints.map(({ label, endpoint }) => `  ${label.padEnd(width)}  ${endpoint}`),
            input.text.apply(endpoints.length),
        ];
    return [
        ...lines,
        input.text.urlNote(input.tunnelId ?? ""),
        `Tunnel: ${input.text.label} -> ${input.localUrl}, Teams messaging paths only. Press Ctrl-C to stop.`,
        "",
    ].join("\n");
}
async function planTeamsTunnel(input) {
    const choice = input.tunnel ?? { kind: "cloudflared" };
    if (choice.kind === "cloudflared") {
        return {
            text: TUNNEL_TEXT.cloudflared,
            open: (proxyUrl) => (input.openTunnel ?? openQuickTunnel)({
                localUrl: proxyUrl,
                signal: input.signal,
                spawnImpl: input.spawnImpl,
            }),
        };
    }
    if (input.dir === undefined) {
        throw new CliError("a dev tunnel needs the project directory.");
    }
    const ready = await ensureDevTunnel({
        dir: input.dir,
        tunnelId: choice.tunnelId,
        port: input.port,
        signal: input.signal,
        exec: input.exec,
    }).catch((error) => {
        if (input.signal.aborted) {
            return undefined;
        }
        throw error;
    });
    if (ready === undefined || input.signal.aborted) {
        return undefined;
    }
    return {
        text: TUNNEL_TEXT.devtunnel,
        tunnelId: ready.tunnelId,
        proxyPort: ready.port,
        open: () => openDevTunnel({
            tunnelId: ready.tunnelId,
            port: ready.port,
            signal: input.signal,
            spawnImpl: input.spawnImpl,
        }),
    };
}
async function startTunnelProxy(input) {
    try {
        return await startTeamsPathProxy({
            upstream: input.localUrl,
            paths: input.paths,
            port: input.port,
        });
    }
    catch (error) {
        if (input.port !== undefined && unknownErrorCode(error) === "EADDRINUSE") {
            throw new CliError(`port ${input.port} is in use. The dev tunnel forwards it to the Teams proxy. Stop the process that holds it.`);
        }
        throw error;
    }
}
/**
 * Opens one tunnel that reaches only the targets' messaging paths on
 * `localUrl`, prints every endpoint, and holds the tunnel until `signal`
 * aborts or the tunnel process exits. Returns 0 after a stop request, else
 * the process exit code.
 */
export async function runTeamsTunnel(input) {
    const { signal } = input;
    const plan = await planTeamsTunnel(input);
    if (plan === undefined) {
        return 0;
    }
    const proxy = await startTunnelProxy({
        localUrl: input.localUrl,
        paths: input.targets.map(channelRoutePath),
        port: plan.proxyPort,
    });
    try {
        const tunnel = await plan.open(proxy.url).catch((error) => {
            if (signal.aborted) {
                return undefined;
            }
            throw error;
        });
        if (tunnel === undefined || signal.aborted) {
            return 0;
        }
        input.out(formatTunnelReady({
            publicUrl: tunnel.publicUrl,
            localUrl: input.localUrl,
            targets: input.targets,
            json: input.json === true,
            text: plan.text,
            tunnelId: plan.tunnelId,
        }));
        const code = await Promise.race([tunnel.exited, whenAborted(signal).then(() => 0)]);
        // Ctrl-C reaches the tunnel process too, so its close can land just before the stop request.
        if (signal.aborted) {
            await tunnel.exited;
            return 0;
        }
        input.err(`${plan.text.label} exited with code ${code}.\n`);
        return code;
    }
    finally {
        await proxy.close();
    }
}
function firstLine(text) {
    return text.split("\n", 1)[0] ?? text;
}
/**
 * Opens the Teams tunnel for `agent-sdk dev` when an agent on the server has a
 * Teams channel. Never rejects: a failure is one warning line on `err`, and
 * the server keeps serving.
 */
export async function startDevTeamsTunnel(input) {
    const out = input.out ?? ((text) => void process.stdout.write(text));
    const err = input.err ?? ((text) => void process.stderr.write(text));
    const warn = (reason) => err(`warning: Teams tunnel: ${reason}\n`);
    const choice = input.tunnel ?? { kind: "cloudflared" };
    try {
        const targets = teamsChannelTargets(input.handle.agents);
        if (targets.length === 0) {
            const idleWarning = TUNNEL_TEXT[choice.kind].idleWarning;
            if (idleWarning !== undefined) {
                warn(idleWarning);
            }
            return;
        }
        await runTeamsTunnel({
            localUrl: input.handle.url,
            targets,
            signal: input.signal,
            out,
            err: (text) => warn(text.trim()),
            tunnel: choice,
            dir: input.dir,
            port: input.port,
            exec: input.exec,
            spawnImpl: input.spawnImpl,
            openTunnel: input.openTunnel,
        });
    }
    catch (error) {
        const hint = error instanceof CliError && error.hint !== undefined ? ` ${error.hint}` : "";
        warn(`${firstLine(describeError(error))}${hint}`);
    }
}
/**
 * Agents from host `GET /v1/health`, then each agent's channels from its info
 * route. A health body with no `agents` array is one single-mode mount at
 * `/v1/info` (empty slug). Multi-mode lists `{ slug }` and serves info at
 * `/<slug>/v1/info`.
 */
async function readServedAgents(input) {
    const health = await fetchServerJson({
        baseUrl: input.baseUrl,
        path: "/v1/health",
        bearerToken: input.bearerToken,
    });
    const agents = [];
    for (const slug of slugsFromHealth(health)) {
        const path = agentInfoPath(slug);
        const info = await fetchServerJson({
            baseUrl: input.baseUrl,
            path,
            bearerToken: input.bearerToken,
        });
        agents.push({ slug, info: { channels: readChannels(info, path) } });
    }
    return agents;
}
function slugsFromHealth(body) {
    if (!isRecord(body)) {
        throw new CliError("GET /v1/health did not return a health document.");
    }
    if (!Array.isArray(body.agents)) {
        return [""];
    }
    return body.agents.map((agent) => {
        if (!isRecord(agent) || typeof agent.slug !== "string") {
            throw new CliError("GET /v1/health listed an agent without a slug.");
        }
        return agent.slug;
    });
}
function agentInfoPath(slug) {
    if (slug === "") {
        return "/v1/info";
    }
    if (slug.includes("/") || slug.includes("\\") || slug === "." || slug === "..") {
        throw new CliError(`GET /v1/health listed an agent slug that is not a path segment: ${slug}`);
    }
    return `/${slug}/v1/info`;
}
function readChannels(body, path) {
    if (!isRecord(body) || !Array.isArray(body.channels)) {
        throw new CliError(`GET ${path} did not return agent info.`);
    }
    return body.channels.map((channel) => readChannel(channel, path));
}
function readChannel(channel, path) {
    if (!isRecord(channel) || typeof channel.id !== "string" || !Array.isArray(channel.routes)) {
        throw new CliError(`GET ${path} returned a channel without an id and routes.`);
    }
    const routes = [];
    for (const route of channel.routes) {
        if (!isRecord(route) || typeof route.method !== "string" || typeof route.path !== "string") {
            throw new CliError(`GET ${path} returned a channel route without a method and path.`);
        }
        routes.push({ method: route.method, path: route.path });
    }
    return {
        id: channel.id,
        kind: typeof channel.kind === "string" ? channel.kind : undefined,
        routes,
    };
}
async function fetchServerJson(input) {
    let response;
    try {
        response = await fetch(`${input.baseUrl}${input.path}`, {
            headers: mergeRequestHeaders({ bearerToken: input.bearerToken }),
        });
    }
    catch (error) {
        throw new CliError(`Could not reach ${input.baseUrl}. Start \`${CLI} serve\`, then point \`${CLI} channels teams forward\` at that host and port.`, { code: "unavailable", cause: error });
    }
    const text = await response.text();
    if (!response.ok) {
        const code = errorCodeForStatus(response.status);
        throw new CliError(`GET ${input.path} returned HTTP ${response.status}.`, {
            code,
            hint: code === "unauthenticated" || code === "permission_denied"
                ? `Pass the token from \`${CLI} serve --bearer-token\`.`
                : undefined,
        });
    }
    try {
        return JSON.parse(text);
    }
    catch (error) {
        throw new CliError(`GET ${input.path} did not return JSON.`, { cause: error });
    }
}
export async function cmdTeamsForward(options) {
    const out = options.out ?? ((text) => void process.stdout.write(text));
    const err = options.err ?? ((text) => void process.stderr.write(text));
    const localUrl = `http://${options.host ?? DEFAULT_HOST}:${options.port ?? DEFAULT_PORT}`;
    const served = teamsChannelTargets(await readServedAgents({ baseUrl: localUrl, bearerToken: options.bearerToken }));
    if (served.length === 0) {
        throw new CliError(`no Teams channel found on the server at ${localUrl}. Add one with \`${CLI} channels teams init\`, then restart \`${CLI} serve\`.`);
    }
    const targets = selectTeamsChannelProfiles(served, {
        dir: options.dir,
        slug: options.slug,
        channel: options.channel,
    });
    const choice = options.tunnel ?? { kind: "cloudflared" };
    const stop = new AbortController();
    const requestStop = () => stop.abort();
    process.on("SIGINT", requestStop);
    process.on("SIGTERM", requestStop);
    try {
        if (options.json !== true) {
            out(TUNNEL_TEXT[choice.kind].opening(localUrl));
        }
        return await runTeamsTunnel({
            localUrl,
            targets,
            signal: options.signal === undefined ? stop.signal : AbortSignal.any([stop.signal, options.signal]),
            out,
            err,
            json: options.json,
            tunnel: choice,
            dir: options.dir,
            openTunnel: options.openTunnel,
        });
    }
    finally {
        process.off("SIGINT", requestStop);
        process.off("SIGTERM", requestStop);
    }
}
